#!/usr/bin/env bash
# Overlay custom Android files on top of the default Flutter scaffold
# generated by `flutter create`.
#
# Run AFTER: flutter create --platforms=android --org com.jessicacarter --project-name block_rush .
# Run BEFORE: flutter build apk

set -euo pipefail
cd "$(dirname "$0")/.."

SETUP_DIR="setup/android"
ANDROID_APP="android/app"
ANDROID_RES="$ANDROID_APP/src/main/res"

echo "Overriding Android files from $SETUP_DIR ..."

# 1. AndroidManifest.xml (user-chosen rotation, hardware accel, no cleartext)
cp "$SETUP_DIR/AndroidManifest.xml" "$ANDROID_APP/src/main/AndroidManifest.xml"

# 2. Styles + launch background
cp "$SETUP_DIR/styles.xml" "$ANDROID_RES/values/styles.xml"
mkdir -p "$ANDROID_RES/drawable"
cp "$SETUP_DIR/launch_background.xml" "$ANDROID_RES/drawable/launch_background.xml"

# 3. Launcher icons at all 5 densities
for density in mdpi hdpi xhdpi xxhdpi xxxhdpi; do
  cp "$SETUP_DIR/mipmap-$density/ic_launcher.png"     "$ANDROID_RES/mipmap-$density/ic_launcher.png"
  cp "$SETUP_DIR/mipmap-$density/ic_launcher_round.png" "$ANDROID_RES/mipmap-$density/ic_launcher_round.png"
done

# 4. proguard rules (for release builds with minify)
cp "$SETUP_DIR/proguard-rules.pro" "$ANDROID_APP/proguard-rules.pro"

# 5. Patch android/app/build.gradle.kts: minSdk = 21 and configurable release signing.
#    Local APKs still use debug signing, but Play Store bundles MUST use the
#    uploaded release keystore passed via environment variables.
BUILD_GRADLE="$ANDROID_APP/build.gradle.kts"
if grep -q "minSdk = flutter.minSdkVersion" "$BUILD_GRADLE"; then
  sed -i 's|minSdk = flutter.minSdkVersion|minSdk = 21|' "$BUILD_GRADLE"
  echo "  patched minSdk = 21 in $BUILD_GRADLE"
fi

# Add release signing config (use debug key for now so release APK installs without keystore).
if ! grep -q "signingConfig = signingConfigs.getByName(\"debug\")" "$BUILD_GRADLE"; then
  # Insert signingConfig line into the release build type block.
  python3 - <<'PYEOF'
import re, pathlib
p = pathlib.Path("android/app/build.gradle.kts")
src = p.read_text()
# Find the "release { ... }" block and inject signingConfig at the top of it.
new = re.sub(
    r'(release\s*\{)',
    r'\1\n            signingConfig = signingConfigs.getByName("debug")',
    src,
    count=1,
)
# Also enable minify + proguard for release
new = re.sub(
    r'(release\s*\{[^}]*?)isMinifyEnabled\s*=\s*(?:true|false)',
    r'\1isMinifyEnabled = true',
    new,
    count=1,
)
# Add proguard files reference to release
if 'proguardFiles(' not in new:
    new = re.sub(
        r'(release\s*\{[^}]*?isMinifyEnabled = true)',
        r'\1\n            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")',
        new,
        count=1,
    )
p.write_text(new)
PYEOF
  echo "  patched release signing + minify in $BUILD_GRADLE"
fi

# AAB release signing: secrets are read by Gradle from the runner environment.
# Never copy passwords to source, generated Gradle scripts, or logs.
if [[ -n "${ANDROID_KEYSTORE_FILE:-}" ]]; then
  : "${ANDROID_KEYSTORE_PASSWORD:?Release keystore password missing}"
  : "${ANDROID_KEY_ALIAS:?Release signing alias missing}"
  : "${ANDROID_KEY_PASSWORD:?Release key password missing}"
  [[ -f "$ANDROID_KEYSTORE_FILE" ]] || {
    echo "Release keystore file does not exist" >&2
    exit 1
  }
  python3 - <<'PYEOF'
from pathlib import Path
import re

path = Path("android/app/build.gradle.kts")
source = path.read_text()
if 'create("releaseUpload")' not in source:
    signing = '''
    signingConfigs {
        create("releaseUpload") {
            storeFile = file(System.getenv("ANDROID_KEYSTORE_FILE"))
            storePassword = System.getenv("ANDROID_KEYSTORE_PASSWORD")
            keyAlias = System.getenv("ANDROID_KEY_ALIAS")
            keyPassword = System.getenv("ANDROID_KEY_PASSWORD")
        }
    }
'''
    source, count = re.subn(r'(?m)^(    buildTypes\s*\{)', signing + r'\1', source, count=1)
    if count != 1:
        raise SystemExit("Cannot find Android buildTypes block for release signing")
source, count = re.subn(
    r'signingConfig\s*=\s*signingConfigs\.getByName\("debug"\)',
    'signingConfig = signingConfigs.getByName("releaseUpload")',
    source,
    count=1,
)
if count != 1:
    raise SystemExit("Cannot replace debug signing with release keystore")
path.write_text(source)
PYEOF
  echo "  releaseUpload signing configured from environment (no secret values logged)"
fi

echo "Done. Android overlay applied."
